-- PostgreSQL schema for Slipstream.
--
-- GENERATED FILE: do not edit by hand. Run
--   python llmapi/db/generate_pg_schema.py
-- after changing llmapi/api/src/l04_repo/orm.py. The application also creates
-- these tables itself at startup (Base.metadata.create_all), so this file is
-- for provisioning, review and for a DBA who wants to see the DDL up front.
--
-- Conventions: every id is a TEXT primary key generated by the application
-- (no sequences, no AUTOINCREMENT); every *_ms / created_at / updated_at
-- column is a BIGINT holding Unix milliseconds; JSON payloads are TEXT
-- columns holding a UTF-8 JSON string (never PostgreSQL json/jsonb: the
-- application serialises explicitly and stays SQLite-compatible).


-- admin_users
CREATE TABLE admin_users (
	id VARCHAR(40) NOT NULL, 
	username VARCHAR(64) NOT NULL, 
	password_hash TEXT NOT NULL, 
	created_at BIGINT NOT NULL, 
	updated_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_admin_users_username ON admin_users (username);

-- app_settings
CREATE TABLE app_settings (
	key VARCHAR(64) NOT NULL, 
	value_json TEXT NOT NULL, 
	updated_at BIGINT NOT NULL, 
	updated_by VARCHAR(64) NOT NULL, 
	PRIMARY KEY (key)
);

-- channels
CREATE TABLE channels (
	id VARCHAR(40) NOT NULL, 
	slug VARCHAR(64) NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	connection_url TEXT NOT NULL, 
	api_key_enc TEXT NOT NULL, 
	protocol VARCHAR(32) NOT NULL, 
	auth_style VARCHAR(32) NOT NULL, 
	protocol_source VARCHAR(16) NOT NULL, 
	priority INTEGER NOT NULL, 
	timeout_s INTEGER DEFAULT '60' NOT NULL, 
	rewrite_rules_json TEXT NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	note TEXT NOT NULL, 
	connection_status VARCHAR(16) NOT NULL, 
	connection_latency_ms INTEGER, 
	connection_message TEXT NOT NULL, 
	connection_tested_at BIGINT, 
	created_at BIGINT NOT NULL, 
	updated_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_channels_slug ON channels (slug);

-- combos
CREATE TABLE combos (
	id VARCHAR(40) NOT NULL, 
	name VARCHAR(64) NOT NULL, 
	description TEXT NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	failover_rules_json TEXT NOT NULL, 
	max_attempts INTEGER NOT NULL, 
	created_at BIGINT NOT NULL, 
	updated_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_combos_name ON combos (name);

-- daily_aggregates
CREATE TABLE daily_aggregates (
	id VARCHAR(40) NOT NULL, 
	day_ms BIGINT NOT NULL, 
	channel_id VARCHAR(40), 
	model_key VARCHAR(160) NOT NULL, 
	requests INTEGER NOT NULL, 
	prompt_tokens INTEGER NOT NULL, 
	completion_tokens INTEGER NOT NULL, 
	cached_tokens INTEGER NOT NULL, 
	cost_usd DOUBLE PRECISION NOT NULL, 
	errors INTEGER NOT NULL, 
	ttft_p95_ms INTEGER NOT NULL, 
	total_p95_ms INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_daily_aggregate UNIQUE (day_ms, channel_id, model_key)
);

CREATE INDEX ix_daily_aggregates_day_ms ON daily_aggregates (day_ms);

-- ledger_adjustments
CREATE TABLE ledger_adjustments (
	id VARCHAR(40) NOT NULL, 
	request_id VARCHAR(64) NOT NULL, 
	delta_prompt_tokens INTEGER NOT NULL, 
	delta_completion_tokens INTEGER NOT NULL, 
	delta_cached_tokens INTEGER NOT NULL, 
	delta_cost_usd DOUBLE PRECISION NOT NULL, 
	reason VARCHAR(32) NOT NULL, 
	actor VARCHAR(64) NOT NULL, 
	created_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_ledger_adjustments_created_at ON ledger_adjustments (created_at);

CREATE INDEX ix_ledger_adjustments_request_id ON ledger_adjustments (request_id);

-- model_defaults
CREATE TABLE model_defaults (
	model_id VARCHAR(160) NOT NULL, 
	matched_by VARCHAR(24) NOT NULL, 
	providers_json TEXT NOT NULL, 
	rule_version VARCHAR(16) NOT NULL, 
	fields_json TEXT NOT NULL, 
	pulled_at BIGINT NOT NULL, 
	PRIMARY KEY (model_id)
);

-- request_ledger
CREATE TABLE request_ledger (
	id VARCHAR(40) NOT NULL, 
	request_id VARCHAR(64) NOT NULL, 
	user_id VARCHAR(40), 
	api_key_id VARCHAR(40), 
	final_channel_model_id VARCHAR(40), 
	requested_model VARCHAR(160) NOT NULL, 
	source VARCHAR(16) NOT NULL, 
	http_status INTEGER NOT NULL, 
	error_code VARCHAR(64), 
	prompt_tokens INTEGER NOT NULL, 
	completion_tokens INTEGER NOT NULL, 
	cached_tokens INTEGER NOT NULL, 
	cache_ratio DOUBLE PRECISION NOT NULL, 
	cost_usd DOUBLE PRECISION NOT NULL, 
	usage_estimated BOOLEAN NOT NULL, 
	created_at BIGINT NOT NULL, 
	written_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_request_ledger_api_key_id ON request_ledger (api_key_id);

CREATE INDEX ix_request_ledger_created_at ON request_ledger (created_at);

CREATE UNIQUE INDEX ix_request_ledger_request_id ON request_ledger (request_id);

CREATE INDEX ix_request_ledger_user_id ON request_ledger (user_id);

-- request_logs
CREATE TABLE request_logs (
	id VARCHAR(40) NOT NULL, 
	request_id VARCHAR(64) NOT NULL, 
	upstream_request_id VARCHAR(128) NOT NULL, 
	user_id VARCHAR(40), 
	api_key_id VARCHAR(40), 
	api_key_label VARCHAR(64) NOT NULL, 
	requested_model VARCHAR(160) NOT NULL, 
	resolved_combo_id VARCHAR(40), 
	final_channel_model_id VARCHAR(40), 
	channel_name VARCHAR(128) NOT NULL, 
	upstream_model VARCHAR(128) NOT NULL, 
	response_model VARCHAR(128) NOT NULL, 
	is_stream BOOLEAN NOT NULL, 
	source VARCHAR(16) NOT NULL, 
	http_status INTEGER NOT NULL, 
	error_code VARCHAR(64), 
	error_message TEXT NOT NULL, 
	prompt_tokens INTEGER NOT NULL, 
	completion_tokens INTEGER NOT NULL, 
	cached_tokens INTEGER NOT NULL, 
	cache_ratio DOUBLE PRECISION NOT NULL, 
	cost_usd DOUBLE PRECISION NOT NULL, 
	ttft_ms INTEGER, 
	ttfa_ms INTEGER, 
	ttlt_ms INTEGER, 
	total_ms INTEGER NOT NULL, 
	throughput_tps DOUBLE PRECISION, 
	usage_estimated BOOLEAN NOT NULL, 
	attempts_json TEXT NOT NULL, 
	rewrite_applied BOOLEAN NOT NULL, 
	rewrite_skipped VARCHAR(32) NOT NULL, 
	rewrite_diff_json TEXT NOT NULL, 
	response_headers_json TEXT NOT NULL, 
	params_json TEXT NOT NULL, 
	client_ip VARCHAR(64) NOT NULL, 
	request_headers_json TEXT NOT NULL, 
	forwarded_json TEXT NOT NULL, 
	created_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_request_logs_api_key_id ON request_logs (api_key_id);

CREATE INDEX ix_request_logs_created_at ON request_logs (created_at);

CREATE INDEX ix_request_logs_created_status ON request_logs (created_at, http_status);

CREATE INDEX ix_request_logs_final_channel_model_id ON request_logs (final_channel_model_id);

CREATE UNIQUE INDEX ix_request_logs_request_id ON request_logs (request_id);

CREATE INDEX ix_request_logs_requested_model ON request_logs (requested_model);

CREATE INDEX ix_request_logs_user_id ON request_logs (user_id);

-- users
CREATE TABLE users (
	id VARCHAR(40) NOT NULL, 
	username VARCHAR(64) NOT NULL, 
	display_name VARCHAR(128) NOT NULL, 
	created_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_users_username ON users (username);

-- api_keys
CREATE TABLE api_keys (
	id VARCHAR(40) NOT NULL, 
	user_id VARCHAR(40) NOT NULL, 
	label VARCHAR(64) NOT NULL, 
	key_prefix VARCHAR(16) NOT NULL, 
	key_hash VARCHAR(128) NOT NULL, 
	key_enc TEXT NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	last_used_at BIGINT, 
	created_at BIGINT NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_api_key_user_label UNIQUE (user_id, label), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX ix_api_keys_key_hash ON api_keys (key_hash);

CREATE INDEX ix_api_keys_user_id ON api_keys (user_id);

-- attempts
CREATE TABLE attempts (
	id VARCHAR(40) NOT NULL, 
	log_id VARCHAR(40) NOT NULL, 
	seq INTEGER NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	skipped BOOLEAN NOT NULL, 
	channel_model_id VARCHAR(40), 
	channel_slug VARCHAR(128) NOT NULL, 
	channel_name VARCHAR(128) NOT NULL, 
	upstream_model VARCHAR(128) NOT NULL, 
	http_status INTEGER, 
	error_code VARCHAR(64), 
	message TEXT NOT NULL, 
	ms INTEGER NOT NULL, 
	round INTEGER NOT NULL, 
	at_ms BIGINT, 
	priority_path_json TEXT NOT NULL, 
	request_headers_json TEXT NOT NULL, 
	response_headers_json TEXT NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_attempts_log_seq UNIQUE (log_id, seq), 
	FOREIGN KEY(log_id) REFERENCES request_logs (id) ON DELETE CASCADE
);

CREATE INDEX ix_attempts_channel_name ON attempts (channel_name);

CREATE INDEX ix_attempts_error_code ON attempts (error_code);

CREATE INDEX ix_attempts_status ON attempts (status);

CREATE INDEX ix_attempts_upstream_model_nocase ON attempts (lower(upstream_model));

-- channel_keys
CREATE TABLE channel_keys (
	id VARCHAR(40) NOT NULL, 
	channel_id VARCHAR(40) NOT NULL, 
	label VARCHAR(64) NOT NULL, 
	key_enc TEXT NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	last_used_at BIGINT, 
	created_at BIGINT NOT NULL, 
	updated_at BIGINT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(channel_id) REFERENCES channels (id) ON DELETE CASCADE
);

CREATE INDEX ix_channel_keys_channel_id ON channel_keys (channel_id);

-- channel_models
CREATE TABLE channel_models (
	id VARCHAR(40) NOT NULL, 
	channel_id VARCHAR(40) NOT NULL, 
	upstream_model VARCHAR(128) NOT NULL, 
	call_model VARCHAR(128) NOT NULL, 
	model_type VARCHAR(32) DEFAULT 'chat' NOT NULL, 
	model_type_source VARCHAR(16) DEFAULT 'default' NOT NULL, 
	input_price_per_1m DOUBLE PRECISION NOT NULL, 
	output_price_per_1m DOUBLE PRECISION NOT NULL, 
	cache_read_price_per_1m DOUBLE PRECISION, 
	cache_write_price_per_1m DOUBLE PRECISION, 
	parameters_json TEXT NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	banned_until BIGINT, 
	schedule_json TEXT NOT NULL, 
	cooldown_json TEXT NOT NULL, 
	health_status VARCHAR(16) NOT NULL, 
	consecutive_failures INTEGER NOT NULL, 
	consecutive_trip_count INTEGER NOT NULL, 
	escalation_trip_count INTEGER NOT NULL, 
	opened_at BIGINT, 
	cooldown_until BIGINT, 
	half_open_since BIGINT, 
	fault_until BIGINT, 
	probe_status VARCHAR(16) NOT NULL, 
	probe_latency_ms INTEGER, 
	probe_message TEXT NOT NULL, 
	probed_at BIGINT, 
	probe_default BOOLEAN NOT NULL, 
	created_at BIGINT NOT NULL, 
	updated_at BIGINT NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_channel_call_model UNIQUE (channel_id, call_model), 
	FOREIGN KEY(channel_id) REFERENCES channels (id) ON DELETE CASCADE
);

CREATE INDEX ix_channel_models_call_model ON channel_models (call_model);

CREATE INDEX ix_channel_models_channel_id ON channel_models (channel_id);

-- request_bodies
CREATE TABLE request_bodies (
	request_id VARCHAR(64) NOT NULL, 
	request_body TEXT, 
	upstream_body TEXT, 
	response_body TEXT, 
	response_summary TEXT, 
	reasoning_content TEXT, 
	created_at BIGINT NOT NULL, 
	PRIMARY KEY (request_id), 
	FOREIGN KEY(request_id) REFERENCES request_logs (request_id) ON DELETE CASCADE
);

-- combo_targets
CREATE TABLE combo_targets (
	id VARCHAR(40) NOT NULL, 
	combo_id VARCHAR(40) NOT NULL, 
	target_type VARCHAR(16) NOT NULL, 
	channel_model_id VARCHAR(40), 
	child_combo_id VARCHAR(40), 
	priority INTEGER NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	created_at BIGINT NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_combo_target UNIQUE (combo_id, channel_model_id, child_combo_id), 
	FOREIGN KEY(combo_id) REFERENCES combos (id) ON DELETE CASCADE, 
	FOREIGN KEY(channel_model_id) REFERENCES channel_models (id) ON DELETE RESTRICT, 
	FOREIGN KEY(child_combo_id) REFERENCES combos (id) ON DELETE RESTRICT
);

CREATE INDEX ix_combo_targets_combo_id ON combo_targets (combo_id);

